  const temp = [...organisationUsers];
  for (let i = 0; i < temp.length; i++) {
    let num1 = temp[i].userId;
    let num2 = temp[i].organisationId;

    let matching = temp.filter(
      (x) => x.userId === num1 && x.organisationId === num2,
    );

    if (matching.length > 1) {
      organisationUsers = organisationUsers.filter(
        (x) => !(x.userId === num1 && x.organisationId === num2),
      );
    }
  }

  

  await prisma.user.deleteMany();
  await prisma.organisation.deleteMany();
  await prisma.post.deleteMany();
  await prisma.exponat.deleteMany();
  await prisma.organisationUser.deleteMany();
  await prisma.like.deleteMany();
  await prisma.categorization.deleteMany();
  await prisma.socialPost.deleteMany();
  await prisma.userFollows.deleteMany();
  await prisma.favouriteExponat.deleteMany();
  await prisma.userFollows.deleteMany();

  await prisma.user.createMany({
    data: users,
  });

  await prisma.organisation.createMany({
    data: organisations,
  });

  await prisma.categorization.createMany({
    data: categorizations,
  });

  await prisma.exponat.createMany({
    data: exponats,
  });

  await prisma.post.createMany({
    data: posts,
  });

  await prisma.organisationUser.createMany({
    data: organisationUsers,
    skipDuplicates: true
  });

  await prisma.like.createMany({
    data: likes,
    skipDuplicates: true
  });

  await prisma.userOrganisationFollower.createMany({
    data: favouriteOrganisations,
    skipDuplicates: true
  });

  await prisma.userFollows.createMany({
    data: userFollowers,
    skipDuplicates: true
  })

  // Known login for local development: dev@biosfera.local / biosfera123
  const devUser = await prisma.user.create({
    data: {
      firstName: 'Dev',
      lastName: 'Biosfera',
      username: 'dev',
      email: 'dev@biosfera.local',
      password: await bcrypt.hash('biosfera123', 10),
      location: County.SPLITSKO_DALMATINSKA,
      role: Role.SUPER,
      isActivated: true,
    },
  });

  await prisma.organisationUser.create({
    data: {
      organisationId: organisations[0].id,
      userId: devUser.id,
      role: MemberRole.OWNER,
    },
  });
